-- Seeds the ten 2015 public rooms (welcome lobby, HC lounge, Club NX, game hub, coffee house and its storeroom, three hallways, main office).
-- Run it in Adminer against the hotel database. It is safe to run again.
-- Rooms are owned by the oldest account (see @owner). Each room is backed by ads_background items that carry the room artwork; the images load from @site/images/rooms/.
-- Every slice sits on the door tile. To nudge a slice, change its offsetX or offsetY.
SET @owner = (SELECT MIN(id) FROM users);
SET @site = 'https://retro.steamvaluechecker.com';

DELETE i FROM items i JOIN rooms r ON r.id = i.room_id WHERE r.owner = @owner AND r.model_name IN ('model_wl15','model_hcl15','model_cnx15','model_gh15','model_cof15','model_cofsr15','model_hall1','model_hall2','model_hall3','model_ofc15');
DELETE FROM rooms WHERE owner = @owner AND model_name IN ('model_wl15','model_hcl15','model_cnx15','model_gh15','model_cof15','model_cofsr15','model_hall1','model_hall2','model_hall3','model_ofc15');
DELETE FROM room_models WHERE id IN ('model_wl15','model_hcl15','model_cnx15','model_gh15','model_cof15','model_cofsr15','model_hall1','model_hall2','model_hall3','model_ofc15');

-- Welcome Lobby
SET @room = LAST_INSERT_ID();

